sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float k1;
uniform float k2;
uniform float tangentialX;
uniform float tangentialY;
uniform float scale;
uniform float transparentEdge;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 hs = size * 0.5;
    float2 ctr = center * size;
    float2 d = (coord - ctr) / hs;
    float r2 = dot(d, d);
    float radial = 1.0 + k1 * r2 + k2 * r2 * r2;
    float2 tang = float2(2.0 * tangentialX * d.x * d.y + tangentialY * (r2 + 2.0 * d.x * d.x), tangentialX * (r2 + 2.0 * d.y * d.y) + 2.0 * tangentialY * d.x * d.y);
    float2 p = ctr + (d * radial + tang) / scale * hs;
    float4 r4 = transparentEdge > 0.5 ? texT(p) : tex(p);
    return fin(c, r4, opacity);
}
